const API=localStorage.getItem('nipun_api')||'http://localhost:8000/api';let token=localStorage.getItem('nipun_token'),user=JSON.parse(localStorage.getItem('nipun_user')||'null'),view='overview',cache={},lang=localStorage.getItem('nipun_lang')||'en';const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(path,opt={}){let h=opt.headers||{};if(token)h.Authorization='Bearer '+token;if(opt.body&&!(opt.body instanceof FormData))h['Content-Type']='application/json';let r;try{r=await fetch(API+path,{...opt,headers:h})}catch(err){if(!navigator.onLine&&opt.method==='POST'){queueEvent(path,{body:opt.body instanceof FormData?'form-data':opt.body});toast('Offline: action queued for audit sync');return {queued:true,message:'Queued locally; reconcile before applying the underlying action.'}}throw err}let d=await r.json().catch(()=>({detail:'Unexpected server response'}));if(!r.ok){let detail=d.detail;if(Array.isArray(detail))detail=detail.map(x=>`${(x.loc||[]).slice(-1)[0]||'field'}: ${x.msg||'invalid value'}`).join(' · ');else if(typeof detail==='object')detail=detail.msg||JSON.stringify(detail);throw Error(detail||d.message||`Request failed (${r.status})`)}return d}function queueEvent(type,payload){let q=JSON.parse(localStorage.getItem('nipun_sync_queue')||'[]');q.push({id:crypto.randomUUID(),type,payload,queued_at:new Date().toISOString()});localStorage.setItem('nipun_sync_queue',JSON.stringify(q));updateSyncBadge()}function updateSyncBadge(){let n=JSON.parse(localStorage.getItem('nipun_sync_queue')||'[]').length;let b=$('#syncBtn');if(b)b.textContent=`Sync queue · ${n}`}
function toast(t){let x=$('#toast');x.textContent=t;x.classList.add('show');setTimeout(()=>x.classList.remove('show'),2800)}function showApp(){if(!token){$('#login').classList.remove('hidden');$('#app').classList.add('hidden');return}$('#login').classList.add('hidden');$('#app').classList.remove('hidden');$('#userName').textContent=user.name;$('#userRole').textContent=user.role.replace('_',' ');$('#avatar').textContent=user.name[0];$('#auditNav').style.display=['block_officer','state_admin','admin'].includes(user.role)?'flex':'none';navigate('overview')}
$('#loginForm').onsubmit=async e=>{e.preventDefault();try{let d=await api('/auth/login',{method:'POST',body:JSON.stringify({email:$('#email').value,password:$('#password').value})});token=d.access_token;user=d.user;localStorage.setItem('nipun_token',token);localStorage.setItem('nipun_user',JSON.stringify(user));showApp()}catch(e){toast(e.message)}};$('#logout').onclick=()=>{token=null;user=null;localStorage.removeItem('nipun_token');localStorage.removeItem('nipun_user');showApp()};$('#refresh').onclick=()=>render();document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>navigate(b.dataset.view));function navigate(v){view=v;document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===v));let names={overview:'District intelligence / overview',learners:'Learner intelligence / case management',interventions:'Learning recovery / action tracker',schools:'Delivery network / schools & blocks',map:'Administrative intelligence / block view',insights:'Early warning / learning risk analytics',resources:'Teacher enablement / DIKSHA discovery',benchmarks:'Public evidence / national and state benchmarks',data:'Data exchange / ingestion',governance:'Trust framework / governance',audit:'System accountability / audit trail'};$('#crumb').textContent=names[v].toUpperCase();$('#pageTitle').innerHTML=({overview:'Good afternoon. <span>Let’s move learning forward.</span>',learners:'Learners. <span>Find the gap. Start the action.</span>',interventions:'Interventions. <span>Track what changes.</span>',schools:'Schools & blocks. <span>See where support is needed.</span>',map:'Block intelligence. <span>Prioritise support geographically.</span>',insights:'Risk analytics. <span>Spot learners who need attention.</span>',resources:'Teaching resources. <span>Find competency-aligned activities.</span>',benchmarks:'Public evidence. <span>Compare published learning benchmarks.</span>',data:'Data exchange. <span>Bring existing records into one view.</span>',governance:'Governance. <span>Trust the data. Control its use.</span>',audit:'Audit trail. <span>Every important action leaves a trace.</span>'})[v];render()}
async function render(){let c=$('#content');c.innerHTML='<div class="empty">Loading workspace…</div>';try{if(view==='overview')await overview(c);if(view==='learners')await learnerPage(c);if(view==='interventions')await interventionPage(c);if(view==='schools')await schoolPage(c);if(view==='map')await mapPage(c);if(view==='insights')await insightsPage(c);if(view==='resources')await resourcesPage(c);if(view==='benchmarks')await benchmarksPage(c);if(view==='data')dataPage(c);if(view==='governance')await governancePage(c);if(view==='audit')await auditPage(c)}catch(e){c.innerHTML=`<div class="card"><b>Could not load this view</b><p class="muted">${esc(e.message)}. Check that the API is running on port 8000.</p><button class="primary" onclick="render()">Retry</button></div>`}}
const kpi=(label,value,foot)=>`<div class="card"><div class="kpi-label">${label}</div><div class="kpi-value">${value}</div><div class="kpi-foot">${foot}</div></div>`;
async function overview(c){let d=await api('/dashboard');cache.dashboard=d;$('#riskNav').textContent=d.at_risk;let max=Math.max(...d.by_grade.map(x=>Math.max(x.reading,x.numeracy)),1);c.innerHTML=`<div class="grid kpis">${kpi('LEARNERS MONITORED',d.learners.toLocaleString(),'Across '+d.schools+' participating schools')}${kpi('LEARNERS NEEDING SUPPORT',d.at_risk,`<strong>${d.risk_rate}%</strong> require targeted attention`)}${kpi('AVERAGE READING SCORE',d.avg_reading+' / 100','Baseline diagnostic · demo data')}${kpi('AVERAGE NUMERACY SCORE',d.avg_numeracy+' / 100','Baseline diagnostic · demo data')}</div><div class="section-head"><div><h3>Foundational learning pulse</h3><p>Average competency score by grade · reading vs numeracy</p></div><span class="pill ok">BASELINE VIEW</span></div><div class="grid two-col"><div class="card"><div class="chart">${d.by_grade.map(x=>`<div class="bar-group"><div class="bar read" style="height:${x.reading/max*100}%" title="Reading ${x.reading}"></div><div class="bar math" style="height:${x.numeracy/max*100}%" title="Numeracy ${x.numeracy}"></div><span class="bar-label">Grade ${x.grade}</span></div>`).join('')}</div><div class="legend"><span><i style="background:#2f8068"></i>Reading</span><span><i style="background:#c9dfa6"></i>Numeracy</span></div></div><div class="card"><h3 style="font:800 14px Manrope;margin:0">Priority signals</h3><p class="muted" style="font-size:10px">Where the system should focus next</p><div class="risk-list"><div class="risk-row"><span>At-risk learners</span><div class="track"><div class="fill red" style="width:${d.risk_rate}%"></div></div><b>${d.risk_rate}%</b></div><div class="risk-row"><span>Reading average</span><div class="track"><div class="fill green" style="width:${d.avg_reading}%"></div></div><b>${d.avg_reading}</b></div><div class="risk-row"><span>Numeracy average</span><div class="track"><div class="fill" style="width:${d.avg_numeracy}%"></div></div><b>${d.avg_numeracy}</b></div><div class="risk-row"><span>Actions completed</span><div class="track"><div class="fill green" style="width:${d.interventions?d.completed/d.interventions*100:0}%"></div></div><b>${d.interventions?Math.round(d.completed/d.interventions*100):0}%</b></div></div></div></div><div class="callout"><div><b>Close the loop, not just the report.</b><p>${d.at_risk} learners are flagged by the prototype's illustrative risk rules. Assign a specific remediation and reassess.</p></div><button class="primary" onclick="navigate('learners')">Review priority learners ↗</button></div><p class="muted-note" style="margin-top:14px">${esc(d.source_note)} Scores and risk thresholds are illustrative and are not official PARAKH, ASER or NIPUN Bharat benchmarks.</p>`}
async function learnerPage(c){let q=$('#searchLearner')?.value||'',grade=$('#gradeFilter')?.value||'',risk=$('#riskFilter')?.value||'all';let d=await api(`/learners?q=${encodeURIComponent(q)}&grade=${grade}&risk=${risk}`);c.innerHTML=`<div class="toolbar"><input id="searchLearner" placeholder="Search learner name or ID…" value="${esc(q)}"><select id="gradeFilter"><option value="">All grades</option>${[1,2,3,4,5,6,7,8].map(g=>`<option ${grade==g?'selected':''}>${g}</option>`).join('')}</select><select id="riskFilter"><option value="all">All learners</option><option value="high" ${risk==='high'?'selected':''}>Priority support</option></select><button class="primary" onclick="addLearnerModal()">+ Add learner</button><button class="small-btn" onclick="downloadExport()">Export JSON ↓</button></div><div class="table-wrap"><table><thead><tr><th>Learner</th><th>Grade / School</th><th>Attendance</th><th>Reading</th><th>Numeracy</th><th>Signal</th><th></th></tr></thead><tbody>${d.items.map(x=>`<tr><td><b>${esc(x.name)}</b><br><small>${esc(x.id)}</small></td><td>Grade ${x.grade}<br><small>${esc(x.school_name)}</small></td><td>${x.attendance}%</td><td>${x.reading_score==null?'Not assessed':x.reading_score+'/100'}</td><td>${x.numeracy_score==null?'Not assessed':x.numeracy_score+'/100'}</td><td><span class="pill ${x.risk==='High'?'high':x.risk==='Watch'?'watch':'ok'}">${x.risk}</span></td><td><button class="small-btn" onclick="learnerDetail('${x.id}')">Open →</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty">No learners match this filter.</td></tr>'}</tbody></table></div><p class="muted-note">Risk is a transparent prototype rule using reading &lt; 50, numeracy &lt; 45 or attendance &lt; 75%. It is a triage signal, not a diagnosis.</p>`;$('#searchLearner').oninput=debounce(()=>learnerPage(c),250);$('#gradeFilter').onchange=()=>learnerPage(c);$('#riskFilter').onchange=()=>learnerPage(c)}
function debounce(f,n){let t;return()=>{clearTimeout(t);t=setTimeout(f,n)}}
async function learnerDetail(id){try{let d=await api('/learners/'+id),l=d.learner;modal(`<div class="detail-head"><div><div class="eyebrow">LEARNER PROFILE / ${esc(l.id)}</div><h2 style="font:800 20px Manrope;margin:7px 0">${esc(l.name)}</h2><p class="muted">Grade ${l.grade} · ${esc(l.school_name)}</p></div><span class="pill ${l.reading_score<50||l.numeracy_score<45?'high':'ok'}">${l.reading_score<50||l.numeracy_score<45?'Priority support':'Review progress'}</span></div><div class="score-row"><div class="score-box"><b>${l.reading_score}</b><small>Reading / 100</small></div><div class="score-box"><b>${l.numeracy_score}</b><small>Numeracy / 100</small></div><div class="score-box"><b>${l.attendance}%</b><small>Attendance</small></div></div><h3 style="font:700 13px Manrope">Recommended next action</h3><p class="muted">${l.reading_score<50?'Reading: guided letter-sound practice, familiar-word recognition and short read-aloud sessions.':l.numeracy_score<45?'Numeracy: concrete counters, number comparison and stepwise addition/subtraction practice.':'Use periodic formative checks to confirm retention and identify the next competency.'}</p><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="primary" onclick="newIntervention('${l.id}',${l.reading_score<50?'reading':l.numeracy_score<45?'numeracy':'reading'})">+ Create intervention</button><button class="small-btn" onclick="submitReassessment('${l.id}','reading')">Reassess reading</button><button class="small-btn" onclick="submitReassessment('${l.id}','numeracy')">Reassess numeracy</button></div><h3 style="font:700 13px Manrope;margin-top:23px">Recent interventions</h3>${d.interventions.map(i=>`<p class="muted">${esc(i.domain)} · ${esc(i.status)} — ${esc(i.recommendation)}</p>`).join('')||'<p class="muted">No interventions recorded yet.</p>'}`)}catch(e){toast(e.message)}}
function modal(html){let m=document.createElement('div');m.className='modal-back';m.id='activeModal';m.innerHTML=`<div class="modal"><div class="modal-head"><div></div><button class="close" onclick="document.getElementById('activeModal').remove()">×</button></div>${html}</div>`;m.onclick=e=>{if(e.target===m)m.remove()};document.body.append(m)}
async function addLearnerModal(){let s=await api('/schools');modal(`<h3 style="font:800 17px Manrope">Add learner record</h3><form id="learnerForm" class="form-grid"><label class="wide">Learner name<input name="name" required></label><label>Learner ID<input name="id" placeholder="Auto-generate if blank"></label><label>Grade<select name="grade">${[1,2,3,4,5,6,7,8].map(x=>`<option>${x}</option>`)}</select></label><label>School<select name="school_id">${s.items.map(x=>`<option value="${x.id}" ${user.school_id===x.id?'selected':''}>${esc(x.name)}</option>`)}</select></label><label>Gender<select name="gender"><option>NA</option><option>F</option><option>M</option></select></label><label>Attendance %<input name="attendance" type="number" min="0" max="100" value="90" required></label><label>Reading score<input name="reading_score" type="number" min="0" max="100" value="50" required></label><label>Numeracy score<input name="numeracy_score" type="number" min="0" max="100" value="50" required></label><div class="wide"><button class="primary">Save learner</button></div></form>`);$('#learnerForm').onsubmit=async e=>{e.preventDefault();let o=Object.fromEntries(new FormData(e.target));['grade','attendance','reading_score','numeracy_score'].forEach(k=>o[k]=Number(o[k]));if(!o.id)delete o.id;try{await api('/learners',{method:'POST',body:JSON.stringify(o)});$('#activeModal').remove();toast('Learner record created');render()}catch(e){toast(e.message)}}}
async function newIntervention(id,domain){$('#activeModal')?.remove();modal(`<h3 style="font:800 17px Manrope">Create learning intervention</h3><form id="intForm" class="form-grid"><input type="hidden" name="learner_id" value="${id}"><label>Learning domain<select name="domain"><option ${domain==='reading'?'selected':''}>reading</option><option ${domain==='numeracy'?'selected':''}>numeracy</option></select></label><label>Review due date<input type="date" name="due_date"></label><label class="wide">Identified competency gap<input name="gap" required placeholder="e.g. Cannot decode simple two-letter words"></label><label class="wide">Recommended classroom action<textarea name="recommendation" required>${domain==='reading'?'10-minute daily letter-sound and familiar-word practice using locally available word cards.':'Use counters/number line for concrete addition and subtraction practice; reassess with 5 items.'}</textarea></label><label class="wide">Teacher notes<textarea name="notes"></textarea></label><div class="wide"><button class="primary">Add to action tracker</button></div></form>`);$('#intForm').onsubmit=async e=>{e.preventDefault();let o=Object.fromEntries(new FormData(e.target));try{await api('/interventions',{method:'POST',body:JSON.stringify(o)});$('#activeModal').remove();toast('Intervention assigned');navigate('interventions')}catch(e){toast(e.message)}}}
async function interventionPage(c){let d=await api('/interventions');c.innerHTML=`<div class="section-head" style="margin-top:0"><div><h3>Intervention action tracker</h3><p>Track the response, not just the learner's risk score.</p></div><select id="statusFilter" class="small-btn"><option value="all">All statuses</option>${['Planned','In progress','Completed','Deferred'].map(s=>`<option>${s}</option>`)}</select></div><div class="table-wrap"><table><thead><tr><th>Learner</th><th>Domain / gap</th><th>Recommended action</th><th>Due</th><th>Status</th><th>Update</th></tr></thead><tbody id="intRows">${d.items.map(intRow).join('')||'<tr><td colspan="6" class="empty">No interventions yet. Open a learner profile to create one.</td></tr>'}</tbody></table></div>`;$('#statusFilter').onchange=async()=>{let x=await api('/interventions?status='+encodeURIComponent($('#statusFilter').value));$('#intRows').innerHTML=x.items.map(intRow).join('')||'<tr><td colspan="6" class="empty">No matching interventions.</td></tr>'}}
function intRow(i){return `<tr><td><b>${esc(i.learner_name)}</b><br><small>Grade ${i.grade} · ${esc(i.school_name)}</small></td><td>${esc(i.domain)}<br><small>${esc(i.gap)}</small></td><td style="max-width:280px;white-space:normal">${esc(i.recommendation)}</td><td>${esc(i.due_date||'—')}</td><td><span class="pill ${i.status==='Completed'?'ok':i.status==='In progress'?'watch':'high'}">${esc(i.status)}</span></td><td><select class="small-btn" onchange="updateInt(${i.id},this.value)"><option value="">Update…</option>${['Planned','In progress','Completed','Deferred'].map(s=>`<option>${s}</option>`)}</select></td></tr>`}async function updateInt(id,status){if(!status)return;try{await api('/interventions/'+id,{method:'PATCH',body:JSON.stringify({status,notes:''})});toast('Status updated');render()}catch(e){toast(e.message)}}
async function schoolPage(c){let d=await api('/schools');c.innerHTML=`<div class="section-head" style="margin-top:0"><div><h3>${d.items.length} schools in your permitted view</h3><p>Named directory records are separated from synthetic demonstration schools.</p></div><span class="pill ok">${d.items.filter(x=>x.udise_code).length} DIRECTORY RECORDS</span></div><div class="toolbar"><input id="schoolSearch" placeholder="Search school or block…"><select id="schoolBlock" class="small-btn"><option value="all">All blocks</option>${[...new Set(d.items.map(x=>x.block))].sort().map(b=>`<option>${esc(b)}</option>`).join('')}</select></div><div id="schoolGrid" class="grid panel-grid">${d.items.map(s=>schoolCard(s)).join('')}</div><p class="muted-note" style="margin-top:18px">School names and UDISE codes are public directory metadata where shown. Learner counts and all learning/attendance metrics are synthetic demonstration data. Teacher accounts are restricted to their assigned school; block/state accounts see wider authorised scopes.</p>`;const filter=()=>{let q=$('#schoolSearch').value.toLowerCase(),b=$('#schoolBlock').value;$('#schoolGrid').innerHTML=d.items.filter(x=>(b==='all'||x.block===b)&&(`${x.name} ${x.block} ${x.udise_code||''}`).toLowerCase().includes(q)).map(schoolCard).join('')||'<div class="card">No schools match.</div>'};$('#schoolSearch').oninput=filter;$('#schoolBlock').onchange=filter}function schoolCard(s){return `<div class="card school-card"><div class="eyebrow">${esc(s.block)} · ${s.udise_code?`UDISE ${esc(s.udise_code)}`:esc(s.id)}</div><span class="pill ${s.udise_code?'ok':'watch'}">${s.udise_code?'PUBLIC DIRECTORY RECORD':'SYNTHETIC SCHOOL'}</span><h4 style="margin-top:12px">${esc(s.name)}</h4><p>${esc(s.district)}, ${esc(s.state)}</p><div class="school-metrics"><div><b>${s.learners}</b><small>LEARNERS</small></div><div><b>${s.reading||0}</b><small>READING</small></div><div><b>${s.numeracy||0}</b><small>NUMERACY</small></div><div><b>${s.attendance||0}%</b><small>ATTENDANCE</small></div></div></div>`}
function dataPage(c){c.innerHTML=`<div class="grid two-col"><div class="card"><h3 style="font:800 15px Manrope;margin-top:0">Authorised state assessment import</h3><p class="muted">Ingest pseudonymous learner-level records from an approved state export. School, grade, domain, score, competency and source lineage are validated row by row.</p><div class="callout" style="margin:15px 0"><div><b>Canonical contract · v2.0</b><p>learner_id, school_udise_code, grade, assessment_date, domain, competency_code, score, source_system, source_record_id, attendance_pct</p></div><button class="small-btn" id="newTemplate">Download template ↓</button></div><label style="font-size:11px;font-weight:700">Data-sharing approval/reference ID<input id="assessmentApprovalRef" placeholder="Approval / DSA reference" style="display:block;width:100%;margin:8px 0 12px;padding:11px;border:1px solid var(--line);border-radius:8px"></label><label style="font-size:11px;font-weight:700">Select authorised CSV<input type="file" id="stateCsv" accept=".csv" style="display:block;margin:10px 0 15px"></label><button class="primary" id="stateImport">Validate & import ↗</button><div id="importResult"></div><p class="muted-note">Restricted to block/state/admin roles. Use approved pseudonymous IDs only. No Aadhaar, names or unauthorised child-level records.</p></div><div class="card"><h3 style="font:800 15px Manrope;margin-top:0">Source integration boundaries</h3>${[['UDISE+','School master, enrolment and attendance','Authorised export / connector'],['State assessment systems','Learner-level scores, competencies and dates','Validated CSV adapter'],['PARAKH','National assessment aggregates and frameworks','Aggregate mapping only'],['ASER','Survey-based foundational learning estimates','Survey aggregate only'],['DIKSHA','Teacher-facing learning resources','Catalogue discovery; no live API claim']].map(x=>`<div style="padding:12px 0;border-bottom:1px solid var(--line)"><b style="font-size:12px">${x[0]}</b><p class="muted" style="margin:4px 0">${x[1]}</p><small style="font-size:9px;color:var(--green);font-weight:800">${x[2]}</small></div>`).join('')}</div></div><div class="section-head"><div><h3>Import audit trail</h3><p>Batch status, accepted rows and validation failures.</p></div></div><div id="batchList" class="table-wrap">Loading batches…</div><div class="section-head"><div><h3>Governed data pipeline</h3><p>Every observation retains source lineage and duplicate protection.</p></div></div><div class="mapping"><div class="mapping-item"><b>1. Validate identity</b><p>Match pseudonymous learner, UDISE school and grade before accepting a row.</p></div><div class="mapping-item"><b>2. Preserve competency</b><p>Store source competency codes and domain; do not flatten distinct skills into a misleading common score.</p></div><div class="mapping-item"><b>3. Preserve lineage</b><p>Record source system, source row ID, batch, import actor and assessment date.</p></div><div class="mapping-item"><b>4. Reconcile safely</b><p>Idempotent source-row keys prevent duplicate observations on repeated uploads.</p></div></div>`;c.insertAdjacentHTML('beforeend',`<div class="card" style="margin-top:18px"><h3 style="font:800 15px Manrope;margin-top:0">School master import · UDISE+</h3><p class="muted">Upsert school directory metadata before learner assessment imports. Required: school_udise_code, school_name, block, district, state.</p><input type="file" id="schoolMasterCsv" accept=".csv"><button class="primary" id="schoolMasterImport" style="margin-left:10px">Import school master ↗</button><div id="schoolMasterResult"></div><p class="muted-note">Use an authorised/publicly reusable school master file. This does not create learner outcomes or imply ASER/PARAKH participation.</p></div><div class="card" style="margin-top:18px"><h3 style="font:800 15px Manrope;margin-top:0">Pseudonymous learner roster import</h3><p class="muted">Use only after the data controller has approved the transfer. Required columns: learner_id, school_udise_code, grade, attendance_pct.</p><label>Approval/reference ID<input id="rosterApprovalRef" placeholder="Data-sharing approval ID" style="display:block;width:100%;margin:8px 0;padding:10px;border:1px solid var(--line);border-radius:8px"></label><input type="file" id="rosterCsv" accept=".csv"><button class="primary" id="rosterImport" style="margin-left:10px">Import pseudonymous roster ↗</button><div id="rosterResult"></div><p class="muted-note">Never upload child names, Aadhaar, phone numbers or addresses. Imported learners are marked Not assessed until assessment rows arrive.</p></div><div class="card" style="margin-top:18px"><h3 style="font:800 15px Manrope;margin-top:0">Longitudinal validation readiness</h3><p class="muted">The model will only report metrics when repeated competency observations support a future-term and unseen-school holdout.</p><button class="small-btn" id="validationReadiness">Check readiness ↗</button><div id="validationReadinessResult"></div></div>`);$('#schoolMasterImport').onclick=async()=>{let f=$('#schoolMasterCsv').files[0];if(!f)return toast('Choose school master CSV');let fd=new FormData();fd.append('file',f);try{let r=await api('/import/school-master',{method:'POST',body:fd});$('#schoolMasterResult').innerHTML=`<div class="callout">${r.added} added · ${r.updated} updated · ${r.rejected} rejected</div>`;toast('School master processed')}catch(e){toast(e.message)}};$('#rosterImport').onclick=async()=>{let f=$('#rosterCsv').files[0],ref=$('#rosterApprovalRef').value.trim();if(!f||!ref)return toast('Choose roster CSV and enter approval reference');let fd=new FormData();fd.append('file',f);fd.append('authorisation_reference',ref);try{let r=await api('/import/authorised-roster',{method:'POST',body:fd});$('#rosterResult').innerHTML=`<div class="callout">${r.added} added · ${r.updated} updated · ${r.rejected} rejected</div>`;toast('Pseudonymous roster processed')}catch(e){toast(e.message)}};$('#validationReadiness').onclick=async()=>{try{let r=await api('/validation/readiness');$('#validationReadinessResult').innerHTML=`<div class="callout"><b>${esc(r.validation_gate.toUpperCase())}</b><p>${r.observations.n} observations · ${r.observations.learners} learners · ${r.observations.schools} schools · ${r.observations.dates} dates</p><small>${esc(r.important)}</small></div>`}catch(e){toast(e.message)}};$('#newTemplate').onclick=async()=>{try{let t=await api('/import/template');download(t.required_columns.join(',')+'\n','nipunsetu_state_assessment_template.csv','text/csv')}catch(e){toast(e.message)}};$('#stateImport').onclick=async()=>{let f=$('#stateCsv').files[0];if(!f){toast('Choose a CSV first');return}let form=new FormData();form.append('file',f);form.append('authorisation_reference',$('#assessmentApprovalRef').value.trim());try{let r=await api('/import/state-assessment',{method:'POST',body:form});$('#importResult').innerHTML=`<div class="callout"><b>${r.status.toUpperCase()}</b><p>${r.accepted_rows} accepted · ${r.rejected_rows} rejected · ${r.duplicates_ignored} duplicates ignored</p>${r.errors.slice(0,8).map(x=>`<small>Row ${x.row_number}: ${esc(x.reason)}</small><br>`).join('')}</div>`;loadBatches()}catch(e){toast(e.message)}};loadBatches()}async function loadBatches(){try{let d=await api('/import/batches');$('#batchList').innerHTML=`<table><thead><tr><th>Batch</th><th>Source</th><th>Rows</th><th>Status</th><th>Date</th></tr></thead><tbody>${d.items.map(x=>`<tr><td>${esc(x.id)}</td><td>${esc(x.source_system)}</td><td>${x.accepted_rows}/${x.total_rows}</td><td>${esc(x.status)}</td><td>${esc(x.created_at)}</td></tr>`).join('')||'<tr><td colspan=5>No imports yet.</td></tr>'}</tbody></table>`}catch(e){$('#batchList').textContent=e.message}}
function downloadTemplate(){let csv='learner_id,name,grade,school_id,attendance_pct,reading_score,numeracy_score\nL9001,Demo Learner,3,SCH001,82,42,58\n';download(csv,'nipunsetu_assessment_template.csv','text/csv')};async function uploadCSV(){let f=$('#csvFile').files[0];if(!f)return toast('Choose a CSV file first');let fd=new FormData();fd.append('file',f);try{let d=await api('/import/csv',{method:'POST',body:fd});toast(`${d.rows_processed} records imported`)}catch(e){toast(e.message)}}

async function mapPage(c){let d=await api('/maps/administrative'),groups=Object.values(d.items.reduce((a,x)=>{let g=a[x.block]||(a[x.block]={block:x.block,district:x.district,schools:0,learners:0,reading:0,numeracy:0,attendance:0,risk:0});g.schools++;g.learners+=x.learners||0;g.reading+=(x.reading||0)*(x.learners||0);g.numeracy+=(x.numeracy||0)*(x.learners||0);g.attendance+=(x.attendance||0)*(x.learners||0);g.risk+=(x.risk_rate||0)*(x.learners||0);return a},{})).map(g=>({...g,reading:(g.reading/Math.max(1,g.learners)).toFixed(1),numeracy:(g.numeracy/Math.max(1,g.learners)).toFixed(1),attendance:(g.attendance/Math.max(1,g.learners)).toFixed(1),risk:(g.risk/Math.max(1,g.learners)).toFixed(1)}));c.innerHTML=`<div class="section-head" style="margin-top:0"><div><h3>Administrative coverage</h3><p>Block-level intelligence and school directory coverage. No fabricated map coordinates.</p></div><span class="pill ok">${d.items.length} SCHOOLS · ${groups.length} BLOCKS</span></div><div class="grid panel-grid">${groups.map(g=>`<div class="card" style="border-top:4px solid ${g.risk>55?'#c95e51':g.risk>35?'#f2a65a':'#76a66e'}"><div class="eyebrow">${esc(g.district)}</div><h3 style="font:800 17px Manrope">${esc(g.block)}</h3><div class="school-metrics"><div><b>${g.schools}</b><small>SCHOOLS</small></div><div><b>${g.learners}</b><small>LEARNERS</small></div><div><b>${g.reading}</b><small>READING</small></div><div><b>${g.numeracy}</b><small>NUMERACY</small></div></div><p class="muted-note">Attendance ${g.attendance}% · illustrative gap index ${g.risk}%</p></div>`).join('')}</div><div class="section-head"><div><h3>School-level coverage</h3><p>Each card is linked to its administrative block.</p></div></div><div class="grid panel-grid">${d.items.map(x=>`<div class="card" style="border-top:4px solid ${x.risk_rate>55?'#c95e51':x.risk_rate>35?'#f2a65a':'#76a66e'}"><div class="eyebrow">${esc(x.block)} · ${esc(x.udise_code||x.id)}</div><h3 style="font:800 14px Manrope">${esc(x.name)}</h3><p class="muted-note">${x.learners} learners · Reading ${x.reading||0} · Numeracy ${x.numeracy||0}</p></div>`).join('')}</div><p class="muted-note">${esc(d.geometry)} ${esc(d.note)} Metrics are synthetic, even for schools with public directory names.</p>`}
async function insightsPage(c){let d=await api('/analytics/predictions');c.innerHTML=`<div class="callout"><div><b>Transparent early-warning heuristic</b><p>Weighted reading gap 35% + numeracy gap 35% + attendance gap 30%.</p></div><span class="pill watch">NOT A VALIDATED ML MODEL</span></div><div class="table-wrap" style="margin-top:16px"><table><thead><tr><th>Learner</th><th>Grade / School</th><th>Risk score</th><th>Band</th><th>Recommended action</th><th></th></tr></thead><tbody>${d.items.slice(0,100).map(x=>`<tr><td><b>${esc(x.name)}</b><br><small>${esc(x.learner_id)}</small></td><td>Grade ${x.grade}<br><small>${esc(x.school)}</small></td><td><b>${x.risk_score}</b>/100</td><td><span class="pill ${x.risk_band==='High'?'high':x.risk_band==='Watch'?'watch':'ok'}">${x.risk_band}</span></td><td style="white-space:normal;max-width:310px">${esc(x.recommended_action)}</td><td><button class="small-btn" onclick="learnerDetail('${x.learner_id}')">Open</button></td></tr>`).join('')}</tbody></table></div><p class="muted-note">${esc(d.model)}. ${d.not_a_validated_prediction?'This ranks records for human review; it must not determine access, benefits, grading or punitive action.':''}</p>`;let [impact,cohorts,ml,competencies,effectiveness,readiness]=await Promise.all([api('/analytics/impact'),api('/analytics/cohorts'),api('/analytics/ml-validation'),api('/analytics/competency-outcomes'),api('/analytics/intervention-effectiveness'),api('/validation/readiness')]);const metric=ml.metrics; c.insertAdjacentHTML('afterbegin',`<div class="grid kpis"><div class="card"><div class="kpi-label">READING CHANGE · DEMO</div><div class="kpi-value">+${impact.domains.reading.mean_change}</div><div class="kpi-foot">${impact.domains.reading.pairs} learner-domain pairs</div></div><div class="card"><div class="kpi-label">NUMERACY CHANGE · DEMO</div><div class="kpi-value">+${impact.domains.numeracy.mean_change}</div><div class="kpi-foot">${impact.domains.numeracy.pairs} learner-domain pairs</div></div><div class="card"><div class="kpi-label">COMPETENCY COHORTS</div><div class="kpi-value">${competencies.count}</div><div class="kpi-foot">Paired competency observations</div></div></div><div class="callout"><div><b>Learning progress signal</b><p>${esc(impact.warning)}</p></div></div><div class="section-head"><div><h3>Competency-level progress</h3><p>Earliest vs latest score for learners assessed more than once in the same competency.</p></div></div><div class="table-wrap"><table><thead><tr><th>Block / school</th><th>Grade</th><th>Competency</th><th>Learners</th><th>Baseline</th><th>Latest</th><th>Change</th><th>Improved</th></tr></thead><tbody>${competencies.items.slice(0,30).map(x=>`<tr><td>${esc(x.block)}<br><small>${esc(x.school)}</small></td><td>${x.grade}</td><td>${esc(x.competency_code)}</td><td>${x.learners}</td><td>${x.baseline_mean}</td><td>${x.latest_mean}</td><td>${x.mean_change>0?'+':''}${x.mean_change}</td><td>${x.improved_share}%</td></tr>`).join('')||'<tr><td colspan=8>No repeated competency observations yet. Import longitudinal assessments.</td></tr>'}</tbody></table></div><div class="section-head"><div><h3>Intervention-linked reassessment outcomes</h3><p>${effectiveness.paired_records} reassessments paired with a pre-intervention score.</p></div></div><div class="table-wrap"><table><thead><tr><th>Block</th><th>Domain</th><th>Reassessments</th><th>Mean change</th><th>Positive change</th></tr></thead><tbody>${effectiveness.items.map(x=>`<tr><td>${esc(x.block)}</td><td>${esc(x.domain)}</td><td>${x.reassessments}</td><td>${x.mean_change>0?'+':''}${x.mean_change}</td><td>${x.positive_change_share}%</td></tr>`).join('')||'<tr><td colspan=5>No intervention-linked reassessments yet.</td></tr>'}</tbody></table></div><p class="muted-note">${esc(effectiveness.warning)}</p><div class="section-head"><div><h3>Future learning-gain model validation</h3><p>${esc(ml.model)} · unseen-school + future-time holdout</p></div><span class="pill watch">${readiness.other_source_observations>0?'APPROVAL-REF TAGGED · VERIFY PROVENANCE':'NO APPROVAL-REF TAGGED DATA'}</span></div>${metric?`<div class="grid kpis"><div class="card"><div class="kpi-label">HOLDOUT ACCURACY</div><div class="kpi-value">${(metric.accuracy*100).toFixed(1)}%</div><div class="kpi-foot">Precision ${(metric.precision*100).toFixed(1)}% · Recall ${(metric.recall*100).toFixed(1)}%</div></div><div class="card"><div class="kpi-label">HOLDOUT F1</div><div class="kpi-value">${(metric.f1*100).toFixed(1)}%</div><div class="kpi-foot">Brier ${metric.brier_score}</div></div><div class="card"><div class="kpi-label">CONFUSION MATRIX</div><div class="kpi-foot">TP ${metric.confusion_matrix.true_positive} · FP ${metric.confusion_matrix.false_positive}<br>TN ${metric.confusion_matrix.true_negative} · FN ${metric.confusion_matrix.false_negative}</div></div></div>`:`<div class="callout"><b>${esc(ml.status)}</b><p>${esc(ml.message||'Insufficient outcome diversity for honest held-out evaluation.')}</p></div>`}<p class="muted-note">${esc(ml.validation_status||'External validation is not established.')} Approval-ref tagged observations: ${readiness.other_source_observations}; synthetic/legacy observations excluded from model validation: ${readiness.synthetic_or_legacy_observations}. A reference string is not proof of authorisation; verify the underlying agreement.</p>`)}
async function resourcesPage(c){let d=await api('/resources');c.innerHTML=`<div class="section-head" style="margin-top:0"><div><h3>Competency-aligned teaching activities (${d.count})</h3><p>Curated discovery links to the DIKSHA portal. Verify availability and language before use.</p></div><select id="resourceDomain" class="small-btn"><option value="all">All domains</option><option value="reading">Reading</option><option value="numeracy">Numeracy</option><option value="wellbeing">Wellbeing</option><option value="assessment">Assessment</option><option value="teaching-practice">Teaching practice</option></select><select id="resourceLanguage" class="small-btn"><option value="all">All languages</option><option value="hi">Hindi</option><option value="en">English</option></select></div><div id="resourceGrid" class="grid panel-grid">${d.items.map(resourceCard).join('')}</div><p class="muted-note">${esc(d.integration_status)}</p>`;const refreshResources=async()=>{let x=await api('/resources?domain='+$('#resourceDomain').value+'&language='+$('#resourceLanguage').value);$('#resourceGrid').innerHTML=x.items.map(resourceCard).join('')};$('#resourceDomain').onchange=refreshResources;$('#resourceLanguage').onchange=refreshResources}function resourceCard(x){return `<div class="card"><div class="eyebrow">${esc(x.id)} · ${esc(x.domain.toUpperCase())}</div><h3 style="font:800 14px Manrope">${esc(x.title)}</h3><p class="muted">Grades ${x.grade_min}–${x.grade_max} · ${x.duration_min} min · ${x.language.toUpperCase()}</p><p class="muted-note">${esc(x.format)}</p><a class="primary" style="display:inline-block;text-decoration:none" target="_blank" rel="noopener" href="${esc(x.url)}">Open DIKSHA ↗</a></div>`}
async function submitReassessment(id,domain){let score=Number(prompt(`Enter new ${domain} score (0–100):`));if(!Number.isFinite(score)||score<0||score>100)return toast('Enter a valid score from 0 to 100');try{let d=await api('/reassessments',{method:'POST',body:JSON.stringify({learner_id:id,domain,score,notes:'Teacher-led formative reassessment'})});toast(`Saved. Change: ${d.delta>0?'+':''}${d.delta} points`);learnerDetail(id)}catch(e){toast(e.message)}}
async function syncOfflineQueue(){let q=JSON.parse(localStorage.getItem('nipun_sync_queue')||'[]');if(!q.length)return toast('No pending offline events');try{let d=await api('/sync/batch',{method:'POST',body:JSON.stringify({events:q})});let accepted=new Set(d.accepted);localStorage.setItem('nipun_sync_queue',JSON.stringify(q.filter(x=>!accepted.has(x.id))));updateSyncBadge();toast(`${d.accepted_count} offline events synced`)}catch(e){toast('Sync failed: '+e.message)}}
$('#langToggle')?.addEventListener('click',()=>{lang=lang==='en'?'hi':'en';localStorage.setItem('nipun_lang',lang);$('#langToggle').textContent=lang==='en'?'हिंदी':'English';document.documentElement.lang=lang;const labels=lang==='hi'?{overview:'अवलोकन',learners:'विद्यार्थी',interventions:'हस्तक्षेप',schools:'स्कूल और ब्लॉक',map:'ब्लॉक मानचित्र',insights:'जोखिम विश्लेषण',resources:'DIKSHA संसाधन',benchmarks:'सार्वजनिक बेंचमार्क',data:'डेटा विनिमय',governance:'डेटा शासन',audit:'ऑडिट लॉग'}:{overview:'Overview',learners:'Learners',interventions:'Interventions',schools:'Schools & blocks',map:'Block intelligence map',insights:'Risk analytics',resources:'DIKSHA resources',benchmarks:'Public benchmarks',data:'Data exchange',governance:'Governance',audit:'Audit trail'};document.querySelectorAll('.nav[data-view]').forEach(b=>{let sp=b.querySelector('span');if(sp)sp.textContent=labels[b.dataset.view]||sp.textContent});toast(lang==='hi'?'नेविगेशन हिंदी में उपलब्ध है।':'Navigation set to English')});$('#syncBtn')?.addEventListener('click',syncOfflineQueue);window.addEventListener('online',()=>{if(JSON.parse(localStorage.getItem('nipun_sync_queue')||'[]').length)syncOfflineQueue()});updateSyncBadge();
async function benchmarksPage(c){const d=await api('/public-data/overview');const fmt=x=>Number(x).toLocaleString('en-IN');c.innerHTML=`<div class="grid kpis">${kpi('PUBLISHED BENCHMARKS',d.total_benchmarks,'Officially transcribed aggregate indicators')}${kpi('PARAKH 2024','21.15 lakh','Students assessed · 74,229 schools · 781 districts')}${kpi('ASER 2024','27.1%','Std III rural children reading Std II text · all school types')}</div><div class="callout"><div><b>Evidence boundary matters.</b><p>${esc(d.coverage_note)}</p></div><span class="pill ok">SOURCE-ATTRIBUTED</span></div><div class="section-head"><div><h3>Local-to-public benchmark comparison</h3><p>Compare local school evidence with published indicators without mixing incompatible measures.</p></div><span class="pill ok">COMPARABILITY-AWARE</span></div><div class="card"><div class="toolbar"><select id="compareSchool"></select><select id="compareGrade"><option value="1">Grade 1</option><option value="2">Grade 2</option><option value="3" selected>Grade 3</option><option value="4">Grade 4</option><option value="5">Grade 5</option></select><select id="compareDomain"><option value="reading">Reading</option><option value="numeracy">Numeracy</option></select><button class="primary" id="runCompare">Run comparison</button></div><div id="comparisonResult" class="muted-note">Loading comparison workspace…</div><div class="section-head"><div><h3>Import aligned local observations</h3><p>Only use approved school assessment exports. Exact indicator, unit, population, method and instrument metadata are required.</p></div><button class="small-btn" id="comparisonTemplate">Download local observation template ↓</button></div><div class="toolbar"><input type="file" id="comparisonFile" accept=".csv"><button class="primary" id="comparisonUpload">Validate & import local observations</button></div><div id="comparisonImportResult" class="muted-note">Imported observations retain source and instrument metadata. No learner names are required.</div><div class="section-head"><div><h3>Import source benchmark with protocol metadata</h3><p>Only import a published source figure when its exact population, method and instrument can be documented.</p></div><button class="small-btn" id="referenceTemplate">Download reference template ↓</button></div><div class="toolbar"><input type="file" id="referenceFile" accept=".csv"><button class="primary" id="referenceUpload">Validate & import source reference</button></div><div id="referenceImportResult" class="muted-note">Source URL must be an official education/government HTTPS source.</div></div><div class="section-head"><div><h3>Connected public evidence sources</h3><p>Published source facts and the correct way to use each dataset.</p></div></div><div class="grid panel-grid">${d.sources.map(s=>`<div class="card"><div class="eyebrow">${esc(s.id)}</div><h3 style="font:800 15px Manrope">${esc(s.name)}</h3><p class="muted">${esc(s.publisher)}</p><p>${esc(s.coverage)}</p><p class="muted-note">${esc(s.boundary)}</p><a class="primary" style="display:inline-block;text-decoration:none" target="_blank" rel="noopener" href="${esc(s.url)}">Open official source ↗</a></div>`).join('')}</div><div class="section-head"><div><h3>Published benchmark observations (${d.total_benchmarks})</h3><p>ASER values are percentages of children reaching a task level; PARAKH competency values are percentages of questions answered correctly. They are not interchangeable with local assessment scores.</p></div><button class="small-btn" id="benchmarkTemplate">Download aggregate CSV template ↓</button></div><div class="toolbar"><select id="benchmarkSource"><option value="all">All sources</option><option value="ASER2024">ASER 2024</option><option value="PARAKH2024">PARAKH 2024</option></select><select id="benchmarkDomain"><option value="all">All domains</option><option value="reading">Reading</option><option value="numeracy">Numeracy</option></select></div><div class="table-wrap"><table><thead><tr><th>Source / year</th><th>Geography</th><th>Grade</th><th>Domain</th><th>Indicator</th><th>Value</th><th>Definition</th><th>Provenance</th></tr></thead><tbody id="benchmarkRows"></tbody></table></div><div class="section-head"><div><h3>Import state / district aggregate data</h3><p>Use official report tables or authorised exports. Never upload aggregate ASER/PARAKH rows as learner records.</p></div></div><div class="card"><div class="toolbar"><input type="file" id="benchmarkFile" accept=".csv"><button class="primary" id="benchmarkUpload">Validate & import aggregate CSV</button></div><div id="benchmarkImportResult" class="muted-note">CSV schema and official source URL are validated row by row. Duplicate rows are ignored.</div></div><div class="section-head"><div><h3>Source integration status</h3></div></div><div class="mapping">${Object.entries(d.integration_status).map(([k,v])=>`<div class="mapping-item"><b>${esc(k)}</b><p>${esc(v)}</p></div>`).join('')}</div><p class="muted-note">No live authenticated government API is implied. Officially published report values are seeded with provenance; additional state/district data must be imported from the source's published files or authorised exports.</p>`;const paint=()=>{let rows=d.benchmarks.filter(x=>($('#benchmarkSource').value==='all'||x.source_id===$('#benchmarkSource').value)&&($('#benchmarkDomain').value==='all'||x.domain===$('#benchmarkDomain').value));$('#benchmarkRows').innerHTML=rows.map(x=>`<tr><td><b>${esc(x.source_id)}</b><br><small>${x.year}</small></td><td>${esc(x.geography_name)}<br><small>${esc(x.geography_level)}</small></td><td>${x.grade??'—'}</td><td>${esc(x.domain)}</td><td>${esc(x.indicator)}</td><td><b>${x.value}${x.unit.startsWith('percent')?'%':''}</b><br><small>${esc(x.unit)}</small></td><td style="white-space:normal;min-width:240px">${esc(x.definition)}</td><td><a target="_blank" rel="noopener" href="${esc(x.source_url)}">Source ↗</a><br><small>${esc(x.source_page||'')}</small></td></tr>`).join('')||'<tr><td colspan="8">No matching observations.</td></tr>'};$('#benchmarkSource').onchange=paint;$('#benchmarkDomain').onchange=paint;paint();$('#benchmarkTemplate').onclick=()=>{window.location=API.replace('/api','/api')+'/public-data/template'};const compareSchools=await api('/schools');$('#compareSchool').innerHTML=compareSchools.items.map(x=>`<option value="${esc(x.id)}">${esc(x.name)} · ${esc(x.block)}</option>`).join('');async function runComparison(){try{let q=new URLSearchParams({school_id:$('#compareSchool').value,grade:$('#compareGrade').value,domain:$('#compareDomain').value});let x=await api('/comparison/overview?'+q);let local=x.local||{};$('#comparisonResult').innerHTML=`<div class="grid kpis">${kpi('LOCAL LEARNERS',local.learners??0,'Selected school and grade')}${kpi('LOCAL MEAN SCORE',local.mean_score??'—','0–100 local assessment scale')}${kpi('DIRECT MATCHES',x.direct_comparisons.length,'Only protocol-aligned metrics')}</div><div class="callout"><div><b>Comparison status: context only</b><p>${esc(x.message)}</p></div><span class="pill warn">NO FALSE EQUIVALENCE</span></div><div class="section-head"><div><h3>Protocol-aligned comparisons (${x.direct_comparisons.length})</h3><p>Differences are descriptive percentage-point deltas, not causal effects.</p></div></div><div class="table-wrap"><table><thead><tr><th>Source / geography</th><th>Indicator</th><th>Local</th><th>Reference</th><th>Difference</th></tr></thead><tbody>${x.direct_comparisons.map(z=>`<tr><td>${esc(z.reference.source_id)} · ${esc(z.reference.geography_name)}</td><td>${esc(z.reference.indicator)}</td><td>${z.local_observation.value} ${esc(z.reference.unit)}</td><td>${z.reference.value} ${esc(z.reference.unit)}</td><td><b>${z.difference>0?'+':''}${z.difference} ${esc(z.difference_unit)}</b></td></tr>`).join('')||'<tr><td colspan="5">No exact protocol-aligned pairs yet. Seeded ASER/PARAKH figures remain contextual.</td></tr>'}</tbody></table></div><h3 style="font:800 14px Manrope">Why these values are not directly comparable</h3><ul>${x.rules.map(r=>`<li style="margin:8px 0;color:var(--muted)">${esc(r)}</li>`).join('')}</ul><div class="section-head"><div><h3>Published contextual references (${x.contextual_references.length})</h3><p>Same broad grade/domain filter; methodology differences remain visible.</p></div></div><div class="table-wrap"><table><thead><tr><th>Source</th><th>Geography</th><th>Indicator</th><th>Published value</th><th>Interpretation boundary</th></tr></thead><tbody>${x.contextual_references.map(b=>`<tr><td>${esc(b.source_id)} · ${b.year}</td><td>${esc(b.geography_name)}</td><td>${esc(b.indicator)}</td><td><b>${b.value} ${esc(b.unit)}</b></td><td>${esc(b.reason)}</td></tr>`).join('')||'<tr><td colspan="5">No published reference for this grade/domain.</td></tr>'}</tbody></table></div><p class="muted-note">Local observation imports: ${x.local_observations.length}. A source-compatible benchmark requires matched metric metadata; current ASER/PARAKH seed records are not silently converted into local test scores.</p>`}catch(e){$('#comparisonResult').textContent=e.message}}$('#runCompare').onclick=runComparison;$('#compareSchool').onchange=runComparison;$('#compareGrade').onchange=runComparison;$('#compareDomain').onchange=runComparison;$('#comparisonTemplate').onclick=()=>{window.location=API+'/comparison/template'};$('#referenceTemplate').onclick=()=>{window.location=API+'/comparison/reference-template'};$('#referenceUpload').onclick=async()=>{let f=$('#referenceFile').files[0];if(!f)return toast('Choose a CSV file first');let fd=new FormData();fd.append('file',f);try{let r=await fetch(API+'/comparison/import-reference',{method:'POST',headers:{Authorization:'Bearer '+token},body:fd});let x=await r.json();if(!r.ok)throw Error(typeof x.detail==='string'?x.detail:JSON.stringify(x.detail));$('#referenceImportResult').textContent=`Imported ${x.added}; duplicates ${x.duplicates}; rejected ${x.rejected}. `+x.errors.map(e=>`Row ${e.row}: ${e.reason}`).join(' | ');toast('Source reference import completed');await runComparison()}catch(e){$('#referenceImportResult').textContent=e.message;toast(e.message)}};$('#comparisonUpload').onclick=async()=>{let f=$('#comparisonFile').files[0];if(!f)return toast('Choose a CSV file first');let fd=new FormData();fd.append('file',f);try{let r=await fetch(API+'/comparison/import-local',{method:'POST',headers:{Authorization:'Bearer '+token},body:fd});let x=await r.json();if(!r.ok)throw Error(typeof x.detail==='string'?x.detail:JSON.stringify(x.detail));$('#comparisonImportResult').textContent=`Imported ${x.added}; duplicates ${x.duplicates}; rejected ${x.rejected}. `+x.errors.map(e=>`Row ${e.row}: ${e.reason}`).join(' | ');toast('Local observations imported');await runComparison()}catch(e){$('#comparisonImportResult').textContent=e.message;toast(e.message)}};await runComparison();$('#benchmarkUpload').onclick=async()=>{let f=$('#benchmarkFile').files[0];if(!f)return toast('Choose a CSV file first');let fd=new FormData();fd.append('file',f);try{let r=await fetch(API+'/public-data/import-aggregate',{method:'POST',headers:{Authorization:'Bearer '+token},body:fd});let x=await r.json();if(!r.ok)throw Error(typeof x.detail==='string'?x.detail:JSON.stringify(x.detail));$('#benchmarkImportResult').textContent=`Imported ${x.added}; duplicates ${x.duplicates}; rejected ${x.rejected}. `+x.errors.map(e=>`Row ${e.row}: ${e.reason}`).join(' | ');toast('Aggregate data import completed');}catch(e){$('#benchmarkImportResult').textContent=e.message;toast(e.message)}}}
async function governancePage(c){let d=await api('/governance');c.innerHTML=`<div class="card"><div class="eyebrow">CANONICAL DATA CONTRACT / V1.0</div><h3 style="font:800 16px Manrope">One consistent vocabulary. Multiple source systems.</h3><p class="muted">The interoperability layer maps source-specific fields to a shared schema while preserving lineage. ASER and PARAKH are not assumed to expose identifiable learner-level records.</p><div class="table-wrap" style="margin-top:15px"><table><thead><tr><th>Canonical field</th><th>Type</th><th>Required</th><th>Definition</th></tr></thead><tbody>${d.canonical_fields.map(x=>`<tr><td><b>${x.field}</b></td><td>${x.type}</td><td>${x.required?'Yes':'No'}</td><td>${x.description}</td></tr>`).join('')}</tbody></table></div></div><div class="section-head"><div><h3>Source integration map</h3><p>Realistic integration boundaries for the Indian school data ecosystem.</p></div></div><div class="mapping">${d.source_mappings.map(x=>`<div class="mapping-item"><b>${x.source}</b><p>${x.fields}</p><small>${x.status}</small><p>${x.mode}</p></div>`).join('')}</div><div class="section-head"><div><h3>Data protection & governance controls</h3><p>Designed for responsible public-sector deployment.</p></div></div><div class="grid panel-grid">${d.principles.map((p,i)=>`<div class="card"><div class="eyebrow">CONTROL 0${i+1}</div><p style="font-size:12px;font-weight:700;line-height:1.5">${p}</p></div>`).join('')}</div><p class="muted-note" style="margin-top:16px">${d.disclaimer}</p>`}
async function auditPage(c){let d=await api('/audit');c.innerHTML=`<div class="section-head" style="margin-top:0"><div><h3>Recent system activity</h3><p>Import, create and update events captured for accountability.</p></div><span class="pill ok">LAST 100 EVENTS</span></div><div class="table-wrap"><table><thead><tr><th>Timestamp</th><th>Actor</th><th>Action</th><th>Entity</th><th>Record</th><th>Details</th></tr></thead><tbody>${d.items.map(x=>`<tr><td>${esc(x.created_at)}</td><td>${esc(x.actor||'System')}</td><td><b>${esc(x.action)}</b></td><td>${esc(x.entity)}</td><td>${esc(x.entity_id)}</td><td>${esc(x.details)}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No activity logged yet.</td></tr>'}</tbody></table></div>`}
async function downloadExport(){try{let d=await api('/export/learners');download(JSON.stringify(d,null,2),'nipunsetu_learners_export.json','application/json')}catch(e){toast(e.message)}}function download(data,name,type){let a=document.createElement('a'),url=URL.createObjectURL(new Blob([data],{type}));a.href=url;a.download=name;a.click();URL.revokeObjectURL(url)}
showApp();
